using System;
using Xunit;

public class SymptomDeletionTest
{
    [Fact]
    public void TestSymptomCodeUsage()
    {
        // Arrange
        var symptomCode = "12345";
        var patientConsultationRequests = new List<string> { symptomCode };

        // Act
        var exception = Assert.Throws<Exception>(() => DeleteSymptomCode(symptomCode, patientConsultationRequests));

        // Assert
        Assert.Equal("Symptom Code used, cannot be deleted", exception.Message);
    }

    [Fact]
    public void TestSymptomCodeNotUsed()
    {
        // Arrange
        var symptomCode = "12345";
        var patientConsultationRequests = new List<string>();

        // Act
        DeleteSymptomCode(symptomCode, patientConsultationRequests);

        // Assert
        // No exception should be thrown
    }

    private void DeleteSymptomCode(string symptomCode, List<string> patientConsultationRequests)
    {
        if (patientConsultationRequests.Contains(symptomCode))
        {
            throw new Exception("Symptom Code used, cannot be deleted");
        }
        // Code to delete the symptom code
    }
}
